//! The raw-style-literal ratchet (design spec §5.1, phux-web row).
//!
//! Colours, spacing and type come from `phux-design` (Rust) and
//! `assets/phux-tokens.css` (the page), both generated by phux-brand. This
//! test reads every file under `src/` and `index.html` and counts:
//!
//! - colour literals: `#` and 3 to 8 hex digits, and `rgb(`/`rgba(`;
//! - physical inline properties, which break right-to-left layouts:
//!   `padding-left`/`margin-right`/`border-left`…, and `left:`/`right:`.
//!
//! Owner paths may hold them: `src/ink.rs`, the one module that turns
//! `phux_design` values into CSS. A file's count may never rise above
//! `style_literals.baseline.json`, and a file missing from the baseline must
//! have none. Lowering a count needs no baseline edit.
//!
//! It is an integration test (`[[test]]` in `Cargo.toml`), not a `lib` unit
//! test, because the `lib` suite runs only in a browser and this one reads
//! the source tree through Node's `fs`.

use std::collections::BTreeMap;

use wasm_bindgen::prelude::*;
use wasm_bindgen_test::wasm_bindgen_test;

#[wasm_bindgen(module = "fs")]
extern "C" {
    #[wasm_bindgen(js_name = readFileSync)]
    fn read_file_sync(path: &str, encoding: &str) -> String;
    #[wasm_bindgen(js_name = readdirSync)]
    fn readdir_sync(path: &str, options: &JsValue) -> js_sys::Array;
}

const ROOT: &str = env!("CARGO_MANIFEST_DIR");

/// Files that own token values and may spell them out.
const OWNERS: &[&str] = &["src/ink.rs", "src/style_literals_tests.rs"];

/// Every scanned file, relative to the crate root.
fn sources() -> Vec<String> {
    let options = js_sys::Object::new();
    js_sys::Reflect::set(&options, &"recursive".into(), &true.into()).unwrap();
    let mut files: Vec<String> = readdir_sync(&format!("{ROOT}/src"), &options)
        .iter()
        .filter_map(|entry| entry.as_string())
        .filter(|path| path.ends_with(".rs"))
        .map(|path| format!("src/{path}"))
        .chain(["index.html".to_owned()])
        .filter(|path| !OWNERS.contains(&path.as_str()))
        .collect();
    files.sort();
    files
}

const fn is_word(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_'
}

/// `#` followed by 3 to 8 hex digits and a word boundary.
fn hex_colors(text: &str) -> usize {
    let bytes = text.as_bytes();
    (0..bytes.len())
        .filter(|&i| bytes[i] == b'#')
        .filter(|&i| {
            let digits = bytes[i + 1..]
                .iter()
                .take_while(|b| b.is_ascii_hexdigit())
                .count();
            // A longer hex run is not a colour; neither is one glued to a word.
            (3..=8).contains(&digits) && !bytes.get(i + 1 + digits).copied().is_some_and(is_word)
        })
        .count()
}

/// `rgb(` and `rgba(`, not inside a longer word.
fn rgb_functions(text: &str) -> usize {
    let bytes = text.as_bytes();
    ["rgb(", "rgba("]
        .iter()
        .map(|needle| {
            text.match_indices(needle)
                .filter(|(i, _)| *i == 0 || !is_word(bytes[i - 1]))
                .count()
        })
        .sum()
}

/// `padding-left`, `margin-right`, `border-left`… and `left:`/`right:` as
/// whole words.
fn physical_properties(text: &str) -> usize {
    let bytes = text.as_bytes();
    let mut count = 0;
    for property in ["padding", "margin", "border"] {
        for side in ["left", "right"] {
            count += text.matches(&format!("{property}-{side}")).count();
        }
    }
    for side in ["left", "right"] {
        count += text
            .match_indices(side)
            .filter(|(i, _)| *i == 0 || !is_word(bytes[i - 1]) && bytes[i - 1] != b'-')
            .filter(|(i, _)| {
                let rest = &text[i + side.len()..];
                rest.trim_start_matches([' ', '\t']).starts_with(':')
            })
            .count();
    }
    count
}

fn literals(text: &str) -> usize {
    hex_colors(text) + rgb_functions(text) + physical_properties(text)
}

fn baseline() -> BTreeMap<String, usize> {
    let text = read_file_sync(&format!("{ROOT}/style_literals.baseline.json"), "utf8");
    serde_json::from_str(&text).expect("style_literals.baseline.json is a map of path to count")
}

#[wasm_bindgen_test]
fn no_file_gains_a_raw_style_literal() {
    let baseline = baseline();
    let mut over = Vec::new();
    for path in sources() {
        let found = literals(&read_file_sync(&format!("{ROOT}/{path}"), "utf8"));
        let allowed = baseline.get(&path).copied().unwrap_or(0);
        if found > allowed {
            over.push(format!("{path}: {found} raw style literals, baseline {allowed}"));
        }
    }
    assert!(
        over.is_empty(),
        "use phux-design tokens or var(--phux-…) instead:\n{}",
        over.join("\n")
    );
}

#[wasm_bindgen_test]
fn the_baseline_names_only_files_that_exist() {
    let sources = sources();
    for path in baseline().keys() {
        assert!(sources.contains(path), "stale baseline entry {path}");
    }
}

#[wasm_bindgen_test]
fn the_patterns_match_what_the_spec_names() {
    assert_eq!(hex_colors("color: #0b0b0f; x: #FFF; #E8E5DF14"), 3);
    assert_eq!(hex_colors("#phux-agent-badges #[derive] #123456789"), 0);
    assert_eq!(rgb_functions("rgba(0,0,0,.5) rgb(1 2 3) torgb("), 2);
    assert_eq!(
        physical_properties("padding-left: 8px; left:0; right : 1px; inset-inline-start: 0"),
        3
    );
    assert_eq!(
        physical_properties("|left, right| rect.left() padding-inline-start:"),
        0
    );
}
